export type CartItem = {
  id: string;
  name: string;
  price: number;
  quantity: number;
  image?: string;
};

const GUEST_CART_KEY = "bindaud:guest-cart";

export const readGuestCart = (): CartItem[] => {
  if (typeof window === "undefined") {
    return [];
  }

  try {
    const stored = window.localStorage.getItem(GUEST_CART_KEY);
    return stored ? (JSON.parse(stored) as CartItem[]) : [];
  } catch {
    return [];
  }
};

export const writeGuestCart = (items: CartItem[]) => {
  if (typeof window === "undefined") {
    return;
  }

  window.localStorage.setItem(GUEST_CART_KEY, JSON.stringify(items));
};

export const addGuestCartItem = (item: CartItem) => {
  const current = readGuestCart();
  const existing = current.find((entry) => entry.id === item.id);

  if (existing) {
    existing.quantity += item.quantity;
    writeGuestCart(current);
    return current;
  }

  const next = [...current, item];
  writeGuestCart(next);
  return next;
};

export const clearGuestCart = () => {
  if (typeof window !== "undefined") {
    window.localStorage.removeItem(GUEST_CART_KEY);
  }
};

export const mergeGuestCart = async (userId: string) => {
  const items = readGuestCart();
  if (!items.length) {
    return [];
  }

  const response = await fetch("/api/cart", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ userId, items }),
  });

  if (response.ok) {
    clearGuestCart();
    return items;
  }

  return items;
};
